              "sectionType": "grammar-reading",
              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **4 どういう** (*dō iu*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n店長「明日から、もうバイトに来ないでください。」\n店員「えっ、（ **どういう** ）ことですか。理由を教えてください。」\n*Tenchō: \"Ashita kara, mō baito ni konaide kudasai.\"*\n*Ten'in: \"E', (**dō iu**) koto desu ka. Riyū o oshiete kudasai.\"*\n* **Meaning:**\n*Store manager: \"Starting tomorrow, please don't come to your part-time shift anymore.\"*\n*Employee: \"Huh? **What does that mean / what kind of** thing is that? Please tell me the reason.\"*\n\n---\n\n### Grammar Explanation\n\n* **疑問連体詞「どういう〜」 (N4/N3 Grammar):**\n*どういう* means *\"what kind of / what sort of\"*. The fixed idiomatic question **どういうことですか** asks for clarification, explanation, or the underlying meaning of an unexpected statement (*\"What do you mean by that?\"*).\n*Context clue:* The worker is shocked by sudden termination and immediately demands an explanation (**理由を教えてください**).\n\n---\n\n### Why the Other Options Don't Fit\n\n* **1 あのくらいの (*ano kurai no*):**\nRefers to a known quantity/extent (\"around that degree\"); cannot ask an interrogative question about meaning.\n* **2 どのくらいの (*dono kurai no*):**\nAsks about quantity, duration, or numerical degree (\"how much / how long\"); cannot ask for the meaning of a dismissal.\n* **3 ああいう (*ā iu*):**\nDemonstrative determiner referring to something distant or third-party (\"that kind of\"); cannot form an open inquiry asking what the speaker means."
