              "sectionType": "grammar-reading",
              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **1 あんなに食べたら** (*anna ni tabetara*).\n💡 **Quick Takeaway**: **いくら〜ても + あんなに〜たら** sets a hypothetical limit (*'no matter how much you like it, if you eat that much...'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nいくらチョコレートが好きでも、一度に（ **あんなに食べたら** ）体に良くないだろう。\n*Ikura chokorēto ga suki demo, ichido ni (**anna ni tabetara**) karada ni yokunai darō.*\n* **Meaning:**\n*\"No matter how much you like chocolate, if you eat that much all at once, it probably isn't good for your health.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **いくら〜ても + [Extreme Amount] + たら + [Bad Result]** = no matter how much..., if you do that much...\n* 📖 **Explanation:** いくら〜ても concedes ('no matter how much you love chocolate'), and あんなに食べたら introduces the extreme hypothetical condition ('if someone eats *that* much at once').\n* 🇯🇵 **日本語ポイント:** 「いくら〜ても、あんなに〜たら〜よくない」で「どれほど好きでも極端な量を食べると悪い結果になる」という仮定条件を表します。\n* 🎯 **Exam Clue:** Look for **いくら〜ても (no matter how much)** + **体に良くないだろう (bad result)** → conditional **〜たら**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **2 こんなに食べてみて:** Consecutive *てみて* ('try eating this much') does not form the natural 'if you eat that much' condition here. / 「〜てみて」は文末の推量「〜良くないだろう」につながりません。\n* **3 あれほど食べたいなら:** Means 'if you want to eat that much', which doesn't pair cleanly with eating it causing bad health. / 「食べたいなら」は条件として不自然です。\n* **4 これくらい食べても:** Means 'even if you eat about this much', clashing with the negative warning *良くないだろう*. / 「〜ても、良くない」では逆接が矛盾します。\n"
