              "sectionType": "grammar-reading",
              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **4 見に行くどころではない** (*mi ni iku dokoro dewa nai*).\n💡 **Quick Takeaway**: **V-dict / N + どころではない** means *'far from being able to / in no position to'* (too busy!).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n加藤「週末、一緒に映画を見に行きませんか。」\n高田「すみません。仕事がいそがしくて、映画を（ **見に行くどころではない** ）のです。」\n*Katō: \"Shūmatsu, issho ni eiga o mi ni ikimasen ka.\"\nTakada: \"Sumimasen. Shigoto ga isogashikute, eiga o (**mi ni iku dokoro dewa nai**) no desu.\"*\n* **Meaning:**\n*\"Katō: \"Want to go see a movie together this weekend?\"\nTakada: \"Sorry. Work is so busy that I'm in no position to go see a movie.\"\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb Dict. / Noun] + どころではない** = nowhere near able to / too busy for ~\n* 📖 **Explanation:** どころではない emphasizes that a pressing situation (like intense work) makes it completely impossible to afford the time or leisure to do something else.\n* 🇯🇵 **日本語ポイント:** 「動詞辞書形＋どころではない」は「忙しさや事情のため、〜できるような状況・余裕では全くない」と強く否定する表現です。\n* 🎯 **Exam Clue:** Invitation (**〜ませんか**) + busy refusal (**すみません、仕事がいそがしくて**) → **どころではない** (no time/room for that)!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 見に行くことがない:** Means 'I never go to see movies' (habit/fact), too blunt and misses the 'too busy right now' excuse. / 現在の余裕のなさを表せません。\n* **2 見に行くことではない:** Means 'it's not something to go see', awkward and unidiomatic for refusing an invite. / 断りの表現として不自然です。\n* **3 見に行くところがない:** Means 'there is no place to go see a movie', unrelated to being busy with work. / 「場所がない」の意味になってしまいます。\n"
