              "correctIndex": 1,
              "sectionType": "grammar-reading",
              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **2 上手な人はいない** (*jōzu na hito wa inai*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n姉はある歌手の大ファンで、「彼くらい歌が（ **上手な人はいない** ）」と、必ずライブに行く。\n*Ane wa aru kashu no dai-fan de, 'Kare kurai uta ga (**jōzu na hito wa inai**)' to, kanarazu raibu ni iku.*\n* **Meaning:**\n*\"My older sister is a huge fan of a certain singer, and believing that '**there is no one who is as good at singing** as him', she never fails to go to his live concerts.\"*\n\n---\n\n### Grammar Explanation\n\n* **〜くらい／ほど〜はない (N3 Grammar):**\nGrammatical pattern used to assert that the subject stands at the absolute pinnacle (*\"no one/nothing is as [adjective] as X\"*). It takes *X くらい + [predicate] はない/はいない*.\n*Context clue:* Being a dedicated super-fan (**大ファンで**) who never misses a concert (**必ずライブに行く**) fits the superlative assertion that nobody sings better than him.\n\n---\n\n### Why the Other Options Don't Fit\n\n* **1 上手な人がいるだろう (*jōzu na hito ga iru darō*):**\n\"There are probably people who sing as well as him\"; weakens praise and contradicts enthusiastic fandom.\n* **3 上手な人もいた (*jōzu na hito mo ita*):**\nPast tense with additive *も* (\"there were also people who were good\"); fails to form the superlative comparison.\n* **4 上手な人になりえない (*jōzu na hito ni arienai*):**\n\"Cannot possibly become a skilled person\"; nonsensical critique that directly opposes the sister's admiration."
