              "correctIndex": 2,
              "sectionType": "grammar-reading",
              "instruction": "問題3 つぎの文章を読んで 19 から 23 の中に入る最もよいものを、1・2・3・4から一つえらびなさい。",
              "passageText": "大人になれば\r\n子どものころ、自分の親と同じ年齢になれば、もっと立派な人間になれるのだろうと思っていた。だが、自分が「大人」であると思っていた年齢に19、成長できていない自分に驚く。\r\nたとえば、朝はいつまでも寝ていたいと思うのも、子どものころと同じだ。さらに、仕事が大変なときなど、何度も会社を休みたくなったりする。「風邪で熱が出たから」とうそをついて、本当に会社を休んだことも20。子どものころは、本当に熱があっても、学校へきちんと通っていたのに。また、にんじんやピーマンなど、子どものころきらいだった食べ物は、今でも21-a、料理に入っていると21-b。それなのに、自分の子どもには「好き嫌いをせずに、なんでも食べなさい」とえらそうにしかったりする。\r\n22さぼったり、うまくうそがつけるような大人になった今の自分の心は、子どものころの自分より成長するどころか、悪くなっているのかもしれない。23、自分の父や母も、昔は「大人」だと思っていたが、今の自分のように考え、「大人」になろうとがんばっていたのかと思うと、なんだかあたたかい気持ちになるのだ。",
              "imageSrc": "/images/practice_sets/set_2_passage.jpg",
              "explanation": "The correct answer is **3 なってみると** (*natte miru to*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nだが、自分が「大人」であると思っていた年齢に（ **なってみると** ）、成長できていない自分に驚く。\n*Daga, jibun ga 'otona' de aru to omotte ita nenrei ni (**natte miru to**), seichō dekite inai jibun ni odoroku.*\n* **Meaning:**\n*\"However, **upon actually reaching** the age that I used to think of as being an 'adult', I am surprised at how little I have grown.\"*\n\n---\n\n### Grammar Explanation\n\n* **〜てみると (N3 Grammar):**\nCombines the exploratory auxiliary *〜てみる* (*\"try doing / actually experience\"*) with the conditional discovery particle *と* to express discovering an unexpected reality upon actually experiencing a situation (*\"when I actually experienced... / upon reaching...\"*).\n*Context clue:* The contrastive transition **だが** (*\"however\"*) leads into the personal realization of surprise (**驚く**) when the author actually arrived at adulthood.\n\n---\n\n### Why the Other Options Don't Fit\n\n* **1 なるところに (*naru tokoro ni*):**\n*〜ところ* with spatial/directional *に* does not convey experiential chronological discovery.\n* **2 なったように (*natta yō ni*):**\nExpresses resemblance or simile (\"as if having become\"); the author genuinely did reach this chronological age.\n* **4 なるとしたら (*naru to shitara*):**\nHypothetical counterfactual (\"if it were to happen that...\"); the author has already reached this age in reality."
