              "passageText": "「時間がない」\r\n私たちは、「時間がない」とよく言う。しかし、本当に「時間がない」のだろうか。本当は「時間がある」のにいそがしいふりをしたり、自分をいそがしい状態にしていることも [19] 。\r\nたとえば、こんなことがあった。何日か前、私は仕事に行くために電車に乗った。急いでいたので、携帯電話も音楽プレーヤーも本もすべて忘れてしまった。いつもは、電車に [20] イヤフォンを耳に押し込み、かばんから本や新聞を取り出して、読むことにしている。携帯電話や携帯ゲームプレーヤーでゲームを始めることもある。[21] この日は何も持たずに電車に乗ってしまったので、何もすることがなくなってしまった。\r\n仕方がないので、電車に乗っているあいだ、何もしないで前の席に座る人の動作や窓の外をずっと見ていた。そうしたら、とてもリラックスすることができたのだ。[22] 、私たちには何もしない時間が必要なのかもしれない。私たちは、わざわざ [23] 用事を作り、生活をいそがしくしてしまっているような気がする。本当に「時間がない」のか考えてみるだけで、もっと充実した時間をとりもどすことができるのではないだろうか。",
              "explanation": "The correct answer is **2 しなくてもいい** (*shinakute mo ii*).\n💡 **Quick Takeaway**: **わざわざ + しなくてもいい 用事** = purposely making errands you *don't even need to do*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n私たちは、わざわざ [ 23 **しなくてもいい** ] 用事を作り、生活をいそがしくしてしまっているような気がする。\n*Watashitachi wa, wazawaza [**shinakute mo ii**] yōji o tsukuri, seikatsu o isogashiku shite shimatte iru yō na ki ga suru.*\n* **Meaning:**\n*\"I feel as though we go out of our way to create errands we don't even need to do, making our own lives busy.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **わざわざ + [V-なくてもいい] + [Noun]** = go out of one's way to do unnecessary ~\n* 📖 **Explanation:** Earlier the author asked whether we are truly busy or making ourselves busy. Saying we deliberately create tasks we **don't have to do** (**しなくてもいい用事**) captures the core point!\n* 🇯🇵 **日本語ポイント:** 「本当は時間があるのに自分を忙しくしている」というテーマを受け、「わざわざしなくてもいい（不要な）用事を作り出している」となります。\n* 🎯 **Exam Clue:** Look for **わざわざ (deliberately)** + **〜てしまっている (regrettable self-made busyness)** → **しなくてもいい** (don't need to do)!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 してもいい:** Means 'errands that are okay to do'; misses the point of creating *unnecessary* busyness. / 不要な用事という意味になりません。\n* **3 したほうがいい:** Means 'errands we had better do', the exact opposite of wasting time on needless tasks! / 「すべき用事」では筆者の主張と逆です。\n* **4 すればいい:** Means 'errands one just has to do', doesn't fit modifying 用事 as unnecessary tasks. / 義務や助言のニュアンスで合いません。\n"
