              "sectionType": "grammar-reading",
              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **2 ことに** (*koto ni*).\n💡 **Quick Takeaway**: **Emotion Adj + ことに** introduces how the speaker feels about the event (*'Happily / To my delight, ...'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nうれしい（ **ことに** ）、みんなから結婚のお祝いをもらった。\n*Ureshii (**koto ni**), minna kara kekkon no oiwai o moratta.*\n* **Meaning:**\n*\"To my delight, I received wedding congratulations from everyone.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Emotion Adj / 驚いた・困った] + ことに、〜** = Happily / Surprisingly / Unfortunately, ...\n* 📖 **Explanation:** Attaching ことに to an emotion word (うれしい, 残念な, 驚いた) frames the sentence with the speaker's reaction before stating what happened.\n* 🇯🇵 **日本語ポイント:** 「感情を表す言葉＋ことに」は文頭に置いて「〜な気持ちになることに、なんと…」と気持ちを前置きする文型です。\n* 🎯 **Exam Clue:** Sentence opener: **[Emotion Adj: うれしい/残念な/困った] + ( )、...** → always **ことに**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 ものに:** *うれしいものに* does not form an introductory emotional adverbial clause. / 感情の前置きには使いません。\n* **3 ほどに:** Means 'to the extent that', connects degree rather than framing an opening sentence emotion. / 程度を表します。\n* **4 わけに:** Used in *わけにはいかない* etc., not after emotion adjectives at the start of a sentence. / 文頭の前置きには使いません。\n"
