              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **4 準備し** (*junbi shi*).\n💡 **Quick Takeaway**: **V ます-stem + ようがない** means *'there is no way to...'* (for する verbs, stem is **し** → **しようがない**!).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n試験は明日なのだから、今から（ **準備し** ）ようがない。もうあきらめた。\n*Shiken wa ashita nano da kara, ima kara (**junbi shi**) yō ga nai. Mō akirameta.*\n* **Meaning:**\n*\"Since the exam is tomorrow, there is no way to prepare now. I've already given up.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb ます-stem] + ようがない** (する → **し**ようがない) = no way / impossible to ~\n* 📖 **Explanation:** ようがない attaches strictly to the ます-stem. For Group 3 する verbs like 準備する, the ます-stem is **準備し** → **準備しようがない**.\n* 🇯🇵 **日本語ポイント:** 「動詞ます形語幹＋ようがない」は「〜する方法・手段がない」。「準備する」の語幹は「準備し」です。\n* 🎯 **Exam Clue:** Check verb stem before **ようがない**: **準備する → 準備し（ます）→ 準備しようがない**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 準備:** Bare noun cannot attach to *ようがない* without *し* (*準備ようがない* is wrong). / 「し」が必要です。\n* **2 準備する:** Dictionary form cannot attach to *ようがない*; requires stem *し*. / 辞書形は接続しません。\n* **3 準備して:** Te-form cannot attach to *ようがない*; requires stem *し*. / テ形は接続しません。\n"
