              "explanation": "The correct answer is **4 いただきました** (*itadakimashita*).\n💡 **Quick Takeaway**: **Superior から + いただきました** = humble verb for *'received from my teacher'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n卒業するときに、先生からプレゼントを（ **いただきました** ）。\n*Sotsugyō suru toki ni, sensei kara purezento o (**itadakimashita**).*\n* **Meaning:**\n*\"When I graduated, I humbly received a present from my teacher.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Superior] から [Item] を いただく** = humbly receive from a superior\n* 📖 **Explanation:** いただく is the humble (kenjōgo) form of もらう (*to receive*). Because the giver is 先生から (*from the teacher*), the speaker must use いただきました.\n* 🇯🇵 **日本語ポイント:** 目上の人（先生）から物をもらうときは、謙譲語「いただく（いただきました）」を使います。\n* 🎯 **Exam Clue:** Check the particle **先生から** ('FROM teacher') → speaker is RECEIVING → humble **いただきました**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 あげました (*agemashita*):** Means 'I gave (to someone)', opposite direction of 先生から. / 自分が相手に与える動詞です。\n* **2 さしあげました (*sashiagemashita*):** Humble 'I gave to a superior', which requires 先生に (TO teacher), not 先生から. / 自分が目上に与える動詞です。\n* **3 やりました (*yarimashita*):** Giving to animals/inferiors; wrong direction and rude with 先生. / 目下や動物に与える表現です。\n"
