              "explanation": "The correct answer is **2 こととなっている** (*koto to natte iru*).\n💡 **Quick Takeaway**: **〜こととなっている** states an official rule or established custom (*'it is set/scheduled that...'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n日本では、新しい学年は4月に始まる（ **こととなっている** ）。\n*Nihon de wa, atarashii gakunen wa shigatsu ni hajimaru (**koto to natte iru**).*\n* **Meaning:**\n*\"In Japan, it is established/scheduled that the new school year begins in April.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb Dict.] + こととなっている / ことになっている** = it is ruled/established that...\n* 📖 **Explanation:** こととなっている (slightly more formal than ことになっている) expresses an institutional rule, law, or fixed social system—like Japan's April school year start.\n* 🇯🇵 **日本語ポイント:** 「動詞辞書形＋こととなっている」は「〜ことになっている」の硬い表現で、規則や社会の決まり・制度を表します。\n* 🎯 **Exam Clue:** National/school rule (**日本では** + **4月に始まる**) → **こととなっている**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 ものとなっている (*mono to natte iru*):** *もの* does not form the N3 rule/schedule grammar pattern *こととなっている*. / 制度・予定の決まりには「こと」を使います。\n* **3 わけになっている (*wake ni natte iru*):** Ungrammatical blend; *わけ* expresses reason/conclusion, not institutional rules. / 不自然な組み合わせです。\n* **4 ほどになっている (*hodo ni natte iru*):** *ほど* expresses degree/extent, not scheduled rules. / 程度を表す語で規則には使えません。\n"
