              "explanation": "The correct answer is **3 落ちるに決まっている** (*ochiru ni kimatte iru*).\n💡 **Quick Takeaway**: **〜に決まっている** expresses near-100% certainty (*'is bound to / surely will'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n彼は何も準備をしていないのだから、明日の試験に（ **落ちるに決まっている** ）。\n*Kare wa nani mo junbi o shite inai no da kara, ashita no shiken ni (**ochiru ni kimatte iru**).*\n* **Meaning:**\n*\"Since he hasn't prepared at all, he is bound to fail tomorrow's exam.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb/Adj Plain] + に決まっている** = is bound to / definitely will\n* 📖 **Explanation:** 〜に決まっている expresses the speaker's strong conviction from obvious evidence (*'no doubt about it!'*). **決めている** means *decided on purpose*, whereas **決まっている** is an intransitive certainty!\n* 🇯🇵 **日本語ポイント:** 「普通形＋に決まっている」は根拠から「絶対に〜に違いない」と強く確信する表現です（自分の意志の「決めている」と区別）。\n* 🎯 **Exam Clue:** Strong reason (**〜のだから** = since he didn't prepare at all!) → speaker certainty = **落ちるに決まっている** (not 決めている, and no ところ needed)!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 落ちるに決めている (*ochiru ni kimete iru*):** *決めている* means deciding by one's own will ('decided to fail'?); certainty uses intransitive **決まっている**. / 確信の文型は自動詞「決まっている」です。\n* **2 落ちるところに決めている (*ochiru tokoro ni kimete iru*):** Wrong verb (*決めている*) plus unnecessary *ところ* (*ところ* means 'about to / place'). / 「ところ」も「決めている」も誤りです。\n* **4 落ちるところに決まっている (*ochiru tokoro ni kimatte iru*):** Unnecessary *ところ*; **〜に決まっている** attaches directly to the plain verb *落ちる*. / 動詞普通形に直接「に決まっている」がつきます。\n"
