              "explanation": "The correct answer is **4 吸ってはいけません** (*sutte wa ikemasen*).\n💡 **Quick Takeaway**: **V-て + はいけません** expresses clear prohibition (*'must not'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n小さい子どもは、たばこを（ **吸ってはいけません** ）。\n*Chiisai kodomo wa, tabako o (**sutte wa ikemasen**).*\n* **Meaning:**\n*\"Small children must not smoke cigarettes.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb て-form] + はいけません** = must not / is prohibited\n* 📖 **Explanation:** 〜てはいけません states a strict rule or prohibition (*'you are not allowed to...'*). Fits 'small children' + 'cigarettes' directly.\n* 🇯🇵 **日本語ポイント:** 「動詞て形＋はいけません」は規則や常識として「〜してはいけない（禁止）」を表す基本文型です。\n* 🎯 **Exam Clue:** Rule for kids (**小さい子どもは たばこを〜**) → direct prohibition **吸ってはいけません**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 吸ってもらいません (*sutte moraimasen*):** Means 'I won't have them smoke for me', unnatural for a prohibition. / 「〜してもらう」は禁止になりません。\n* **2 吸うわけではありません (*suu wake dewa arimasen*):** Means 'it doesn't mean they smoke', softening a generalization rather than forbidding it. / 部分否定であり禁止ではありません。\n* **3 吸わなくしてください (*suwanaku shite kudasai*):** Unnatural phrasing; requests not to do something use *吸わないでください*. / 不自然な表現です。\n"
