              "explanation": "The correct answer is **3 でも** (*demo*).\n💡 **Quick Takeaway**: **Noun + でも** highlights an extreme example meaning *'even [a child]'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n子ども（ **でも** ）できる計算をまちがえてしまった。\n*Kodomo (**demo**) dekiru keisan o machigaete shimatta.*\n* **Meaning:**\n*\"I ended up making a mistake on a calculation that even a child can do.\"*\n\n---\n\n### Context & Passage Clue\n\n* 📌 **Pattern:** **[Extreme Example Noun] + でも + [Positive Verb]** = even [a child] can ~\n* 📖 **Explanation:** でも attaches to an extreme low-bar example like 子ども (*child*) to emphasize how easy the task is: 'even a child can do it!'.\n* 🇯🇵 **日本語ポイント:** 「名詞＋でも」は極端な例を挙げて「〜でさえできる（ほど簡単だ）」と強調する助詞です。\n* 🎯 **Exam Clue:** Look for **できる** (affirmative ability!) + **子ども** (low bar) → **子どもでも** (even a child)! (しか requires negative).\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 から:** Means 'from a child', nonsensical here. / 起点になり意味が合いません。\n* **2 だけ:** Means 'only a child can do it', opposite of the intended meaning! / 「子どもだけができる」となり意味が逆です。\n* **4 しか:** Always requires a NEGATIVE verb (*〜しかできない*), whereas here the verb is affirmative *できる*. / 「しか」は後ろに否定形が必要です。\n"
