              "explanation": "The correct answer is **3 ほど** (*hodo*).\n💡 **Quick Takeaway**: **V-dict + ほどだ** expresses high degree (*'so happy that I almost cried'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n彼女の優しい言葉を聞いて、うれしくて涙が出る（ **ほど** ）だった。\n*Kanojo no yasashii kotoba o kiite, ureshikute namida ga deru (**hodo**) datta.*\n* **Meaning:**\n*\"Hearing her kind words, I was so happy that I was on the verge of tears.\"*\n\n---\n\n### Context & Passage Clue\n\n* 📌 **Pattern:** **[Verb/Adj] + ほど（だ）** = to the extent that / so much that...\n* 📖 **Explanation:** ほど indicates how intense an emotion or action is by comparing it to a vivid physical reaction (涙が出る = tears come out).\n* 🇯🇵 **日本語ポイント:** 「動詞辞書形＋ほどだ」は程度や度合いを「〜するくらいだ」と強調する表現です。\n* 🎯 **Exam Clue:** Degree match: **うれしくて (so happy) ＋ 涙が出る (tears come) ＋ だった** → **ほどだ**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 もの:** Means 'something/used to', does not express extent after 涙が出る. / 程度を表しません。\n* **2 こと:** Nominalizer ('fact/thing'), does not indicate high emotional degree here. / 程度の「くらい」になりません。\n* **4 よう:** *涙が出るようだった* means 'it seemed as if tears came out' (uncertain appearance), less natural for own emotion than *ほど*. / 自分の感情の程度には「ほど」を使います。\n"
