              "explanation": "The correct answer is **1 より** (*yori*).\n💡 **Quick Takeaway**: **[Time] + より** is a formal equivalent of **から** (*'starting from 2 years ago'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nあの人は、2年前（ **より** ）ギターを習い始めたそうです。\n*Ano hito wa, ni-nen mae (**yori**) gitā o narai-hajimeta sō desu.*\n* **Meaning:**\n*\"I heard that person started learning the guitar two years ago.\"*\n\n---\n\n### Context & Passage Clue\n\n* 📌 **Pattern:** **[Time / Place] + より** = from ~ (formal equivalent of **から**)\n* 📖 **Explanation:** より not only marks comparisons ('than'), it also serves as a formal starting-point marker meaning 'from [time/place]' (like 午前9時より営業).\n* 🇯🇵 **日本語ポイント:** 助詞「より」は時間や場所の起点「〜から」の改まった表現として使われます（例：本日より）。\n* 🎯 **Exam Clue:** Check meaning: **2年前 (2 years ago) ＋ 始めた (started)** → starting point = **より** (= から)!\n\n---\n\n### Why Other Options Don't Fit\n\n* **2 により:** Means 'due to / by means of' (cause/agent), not a starting time. / 手段や原因を表します。\n* **3 よりも:** Means 'more than', used for comparisons, not starting points. / 比較の表現です。\n* **4 はより:** Ungrammatical particle combination *はより*. / 「は」と「より」は重ねられません。\n"
