              "explanation": "The correct answer is **3 通りに** (*tōri ni*).\n💡 **Quick Takeaway**: **V-dict + 通りに** means *'exactly as [I say / is written]'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n今から私の言う（ **通りに** ）、ノートに書いてください。\n*Ima kara watashi no iu (**tōri ni**), nōto ni kaite kudasai.*\n* **Meaning:**\n*\"Please write in your notebook exactly as I say from now on.\"*\n\n---\n\n### Context & Passage Clue\n\n* 📌 **Pattern:** **[Verb Dict. / た-form] / [Noun の] + 通りに** = just as / in the exact same way as...\n* 📖 **Explanation:** 〜通りに (*tōri ni*) means copying or following an instruction, model, or words accurately without changing them.\n* 🇯🇵 **日本語ポイント:** 「動詞辞書形・た形＋通りに」は「〜と同じように・言ったままに」を表す基本文型です。\n* 🎯 **Exam Clue:** Classic teacher instruction: **私の言う通りに (just as I say)** / **説明書の通りに (as in the manual)**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 なりに:** Means 'in one's own way / suitable to one's level' (usually after nouns like 子どもなりに). / 「それ相応に」の意味で不自然です。\n* **2 ほどに:** Means 'to the extent that', doesn't mean 'just as instructed'. / 程度を表します。\n* **4 そうに:** *言うそうに* is ungrammatical (様態そう attaches to ます-stem, not dictionary form). / 接続が誤っています。\n"
