              "sectionType": "grammar-reading",
              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **3 払うはめになった** (*harau hame ni natta*).\n💡 **Quick Takeaway**: **〜はめになる** means *'ended up in the unfortunate situation of having to...'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nチェックアウトの時間に間に合わず、ホテルに追加でお金を（ **払うはめになった** ）。\n*Chekkuauto no jikan ni maniawazu, hoteru ni tsuika de okane o (**harau hame ni natta**).*\n* **Meaning:**\n*\"Not making it in time for checkout, I ended up having to pay extra money to the hotel.\"*\n\n---\n\n### Context & Passage Clue\n\n* 📌 **Pattern:** **[Verb Dict.] + はめになる** = end up stuck in an unfortunate situation of doing ~\n* 📖 **Explanation:** 〜はめになる always carries frustration/regret about getting stuck having to do something unpleasant because of a mistake or bad circumstance.\n* 🇯🇵 **日本語ポイント:** 「動詞辞書形＋はめになる」は思わぬ失敗などが原因で「困った結果・不本意な状況に陥る」を表します。\n* 🎯 **Exam Clue:** Look for **間に合わず (missed deadline)** + **追加でお金を〜 (extra fee penalty)** → unfortunate **払うはめになった**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 払わせることになった:** Causative ('make someone else pay'), wrong subject—the speaker is the guest paying. / 自分が払う場面なので使役は誤りです。\n* **2 払わすようにした:** Means 'made sure to make someone pay', illogical and ungrammatical role. / 他人に払わせる意味になり不自然です。\n* **4 払わせるようにした:** Causative + intentional effort ('arranged to make someone pay'), doesn't fit missing checkout. / 意図的に払わせる意味で不自然です。\n"
