              "passageText": "働く女性のためのセミナー\r\n今度の日曜日に、働く女性を応援するためのセミナー、「ジョブ・セミナー　働く女性の新しい生き方」の第1回目の講座が、駅前の市民ホールで行われる予定です。\r\n現代の働く女性には、会社員、母、妻、娘など、いろいろな役割があり、いそがしい人が増えています。しかし以前よりいそがしくなった［　19-a　］、手伝ってくれる人がいないのが［　19-b　］。このセミナーでは、さまざまな業界で活躍されている女性が講師となり、全5回の予定で、［　20　］女性の生き方、上手な働き方を参加者とともに考えていきます。\r\nただ講演を聞く［　21　］、質問をしたり、意見を言える方を募集します。\r\n第1回目の講師は、会社を経営する森川花子さんです。「仕事を持つ女性の時間の使い方」をテーマにセミナーを行います。講演のあとに、講師と参加者の方が交流することができるパーティーもあります。\r\n第2回目［　22　］講師の予定など、その他の内容については、市民ホールのホームページで公開しています。参加をご希望の方は、市民ホール事務所まで直接電話でお申し込みください。みなさまのご参加を［　23　］。",
              "imageSrc": "/images/practice_sets/set_8_passage.jpg",
              "explanation": "The correct answer is **3 だけでなく** (*dake de naku*).\n💡 **Quick Takeaway**: **ただ〜だけでなく、〜** means *'not only listening, but also asking questions and speaking up'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nただ講演を聞く［ 21 **だけでなく** ］、質問をしたり、意見を言える方を募集します。\n*Tada kōen o kiku [**dake de naku**], shitsumon o shitari, iken o ieru kata o boshū shimasu.*\n* **Meaning:**\n*\"We are recruiting people who don't just listen to the lecture, but can also ask questions and express opinions.\"*\n\n---\n\n### Context & Passage Clue\n\n* 📌 **Pattern:** **ただ [A] だけでなく、[B]** = not only [A], but also [B]\n* 📖 **Explanation:** ただ〜だけでなく signals that passive listening isn't enough—participants will also actively ask questions and share opinions.\n* 🇯🇵 **日本語ポイント:** 「ただ〜だけでなく」は「〜ばかりでなく、さらに他のことも」と範囲を広げる文型です。\n* 🎯 **Exam Clue:** Look for **ただ (merely)** before the verb + active additions (**質問をしたり、意見を言える**) → **だけでなく**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 だけであり:** Means 'is merely listening', contradicting 'ask questions and give opinions'. / 後半の内容と矛盾します。\n* **2 だけであれば:** Means 'if it were only listening', conditional doesn't fit recruiting active attendees. / 条件になり意味が合いません。\n* **4 だけでなければ:** Means 'unless it is only listening', logical mismatch. / 条件の否定になり不自然です。\n"
