              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **3 次第** (*shidai*).\n💡 **Quick Takeaway**: **V ます-stem + 次第** means *'as soon as [you arrive at the station], please call'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n駅に着き（ **次第** ）、電話をかけてください。\n*Eki ni tsuki (**shidai**), denwa o kakete kudasai.*\n* **Meaning:**\n*\"As soon as you arrive at the station, please give me a call.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb ます-stem] + 次第、[Action]** = as soon as ~ happens, do...\n* 📖 **Explanation:** 〜次第 attaches directly to the ます-stem (着く → 着き＋次第) and always precedes a planned future action/request ('as soon as X happens, I/you will do Y').\n* 🇯🇵 **日本語ポイント:** 「動詞ます形語幹＋次第」は「〜したらすぐに（後ろの行動をする）」を表す硬めの重要文型です。\n* 🎯 **Exam Clue:** Check verb form before the blank: **着き** is the ます-stem! Only **次第** attaches to a ます-stem!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 通りに:** Attaches to dictionary/た-form, not ます-stem *着き*, and means 'just as'. / 接続も意味も合いません。\n* **2 ばかりに:** Attaches to plain form, not ます-stem, and expresses regrettable blame. / 接続も意味も合いません。\n* **4 とたん:** Attaches to た-form (*着いたとたん*), and always reports a past surprise, not a future request. / 「た形＋とたん」で依頼文には使えません。\n"
