              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **2 もしかしたら** (*moshika shitara*).\n💡 **Quick Takeaway**: **もしかしたら〜かもしれない** is a set pair expressing uncertain possibility (*'perhaps / maybe'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n空に雲がたくさん出ているので、（ **もしかしたら** ）雨が降るかもしれません。\n*Sora ni kumo ga takusan dete iru node, (**moshika shitara**) ame ga furu kamoshiremasen.*\n* **Meaning:**\n*\"Because there are many clouds in the sky, perhaps it might rain.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **もしかしたら + 〜かもしれない / 〜かもしれません** = maybe / perhaps ~\n* 📖 **Explanation:** もしかしたら (*maybe/perhaps*) pairs directly with 〜かもしれない to express uncertain possibility.\n* 🇯🇵 **日本語ポイント:** 不確実な可能性や推量を表すときは「もしかしたら〜かもしれない」の呼応を使います。\n* 🎯 **Exam Clue:** Spot **〜かもしれません** at the end → matching adverb is **もしかしたら**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 もしも:** Means 'if' (pairs with conditional *〜たら / 〜ば*), not *〜かもしれない*. / 「もしも〜たら」と仮定条件で呼応します。\n* **3 もし:** Means 'if' (pairs with *〜たら / 〜なら*), not *〜かもしれない*. / 仮定条件の副詞です。\n* **4 もはや:** Means 'already / no longer' (e.g. もはや間に合わない), unrelated to rain possibility. / 「もはや〜ない」などと使います。\n"
