              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **2 行った** (*itta*).\n💡 **Quick Takeaway**: **V た-form + ことがある** asks about past life experience (*'Have you ever been to America?'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nあなたは、今までアメリカへ（ **行った** ）ことがありますか。\n*Anata wa, ima made Amerika e (**itta**) koto ga arimasu ka.*\n* **Meaning:**\n*\"Have you ever been to America before?\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb た-form] + ことがありますか** = Have you ever done ~?\n* 📖 **Explanation:** Talking about past life experience (**今まで** = up until now) always uses the past **た-form + ことがある**.\n* 🇯🇵 **日本語ポイント:** 「動詞た形＋ことがある」は過去の経験「〜したことがある」を表す定番文型です。\n* 🎯 **Exam Clue:** Spot **今まで (ever / until now)** + **ことがありますか** → past **た-form (行った)**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 行き:** ます-stem cannot precede *ことがありますか*. / ます形語幹は接続しません。\n* **3 行くの:** Nominalizer の cannot go before ことがある here; dictionary form 行くことがある means 'sometimes go'. / 経験には「た形」が必要です。\n* **4 行ったの:** Extra *の* before *こと* is ungrammatical (*行ったのことがありますか* is wrong). / 「の」は不要です。\n"
