              "explanation": "The correct answer is **2 わけにはいかない** (*wake ni wa ikanai*).\n💡 **Quick Takeaway**: **〜わけにはいかない** means *'cannot afford to / must not'* due to circumstances or responsibility.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n明日の勝負で優勝できるか決まるので、負ける（ **わけにはいかない** ）。\n*Ashita no shōbu de yūshō dekiru ka kimaru node, makeru (**wake ni wa ikanai**).*\n* **Meaning:**\n*\"Since tomorrow's match decides whether we can win the championship, I cannot afford to lose.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Verb Dict.] + わけにはいかない** = cannot afford to / can't possibly do ~ (given the situation)\n* 📖 **Explanation:** 〜わけにはいかない expresses strong circumstantial or moral obligation not to do something (here: losing a championship-deciding match is unacceptable).\n* 🇯🇵 **日本語ポイント:** 「動詞辞書形＋わけにはいかない」は状況や立場・責任から「どうしても〜することはできない」を表します。\n* 🎯 **Exam Clue:** Contrast: **わけではない** = 'doesn't mean that'; **わけにはいかない** = 'can't afford to / must not'!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 わけではない:** Means 'it doesn't mean I lose', softening an explanation rather than showing determination not to lose. / 「負けるというわけではない」と部分否定の意味になります。\n* **3 ことではない:** Means 'it is not a matter of losing', unidiomatic for resolve. / 「するべきことではない」等の意味になり合いません。\n* **4 ことにはいかない:** Does not exist in Japanese; the idiom strictly uses **わけ**にはいかない. / 「ことにはいかない」という表現はありません。\n"
