              "passageText": "**新しいスタイルの雑誌**\r\n\r\n海外からやってきて、日本に住む人々の生活を紹介する雑誌、「Japan Lifestyle」が全国の書店で発売されました。\r\n\r\nこれまで、新聞や雑誌などで、日本で生活する留学生たちや、日本で仕事をする外国の人々について簡単に紹介されることはありましたが、生活そのものをテーマとした雑誌が発行されるのは［　19　］ことです。\r\n\r\n表紙のデザインも明るく、楽しそうな雑誌です。たくさんのカラフルな写真やイラストを使って、彼らの生活の様子を生き生きと紹介しています。\r\n\r\nこの雑誌は、毎月ではなく<ruby>季刊<rt>きかん</rt></ruby>、［　20　］春、夏、秋、冬と、1年に4回発行される予定です。これまでは、インターネットで予約した読者に対し、通信販売のみを行ってきましたが、予想以上に売れ行きがよかったので、書店で売ることになった［　21　］。\r\n\r\nこの雑誌を発行する出版社は、「この雑誌［　22　］、外国の人たちがなやみや楽しみを、おたがいに聞いたり教えあったりして、彼らの日本での生活が少しでもよいものになればと思う。」と話しています。日本全国で行われる日本人との交流に関する情報も、［　23　］。",
