              "explanation": "The correct answer is **1 泳いだものです** (*oyoida mono desu*).\n💡 **Quick Takeaway**: **V た-form + ものです** wistfully recalls a childhood habit (*'we used to swim...'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n子どものころは、この川でよく（ **泳いだものです** ）。\n*Kodomo no koro wa, kono kawa de yoku (**oyoida mono desu**).*\n* **Meaning:**\n*\"When I was a child, I used to swim in this river often.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Past Marker: 子どものころ/昔] + [Verb た-form] + ものです** = used to do ~\n* 📖 **Explanation:** た形＋ものです expresses nostalgic recollection of things you regularly used to do in the past (unlike 〜たいものだ, which expresses a wish for the future).\n* 🇯🇵 **日本語ポイント:** 「動詞た形＋ものです」は「子どものころ／昔」などとともに「昔よく〜したものだ」と懐かしく思い出す表現です。\n* 🎯 **Exam Clue:** Signal words **子どものころは (when a child)** + **よく (often)** → nostalgic **〜たものです**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **2 泳ぎたいものです:** Expresses a future/general wish ('I wish to swim'), clashing with past *子どものころは*. / 「〜たいものだ」は願望で過去に合いません。\n* **3 泳いだやらず:** Non-existent grammar ending *〜やらず*. / 存在しない文法表現です。\n* **4 泳ぎたいやらず:** Non-existent grammar ending *〜やらず*. / 存在しない文法表現です。\n"
