              "explanation": "The correct answer is **4 とか** (*to ka*).\n💡 **Quick Takeaway**: **〜とか** at sentence end softens hearsay (*'I heard that there was heavy rain...'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n台風が来て、昨日は沖縄では大雨だった（ **とか** ）。\n*Taifū ga kite, kinō wa Okinawa de wa ōame datta (**to ka**).*\n* **Meaning:**\n*\"I heard that a typhoon came and it rained heavily in Okinawa yesterday.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Plain Sentence] + とか** = I heard that... / they say that... (hearsay)\n* 📖 **Explanation:** 〜とか at the end of a sentence reports something heard indirectly without sounding 100% certain—very common in news/weather gossip.\n* 🇯🇵 **日本語ポイント:** 文末の「普通形＋とか」は人づてに聞いた不確かな伝聞「〜だそうだ／〜という話だ」を表します。\n* 🎯 **Exam Clue:** Spot **沖縄では大雨だった ( ) 。** (no extra clause after!) → hearsay **とか**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 のは:** Topic marker *のは* leaves the sentence incomplete without a predicate after it. / 主題を表すので文末で切れません。\n* **2 とを:** Invalid particle pair *とを* at sentence end. / 不自然な助詞の並びです。\n* **3 のを:** Object marker *のを* requires a following verb (like 聞いた). / 後ろに動詞がないと文が成り立ちません。\n"
