              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **2 そんなに** (*sonna ni*).\n💡 **Quick Takeaway**: **そんなに** (*that / so*) refers directly to what the other person just said.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n妻「あなたの体のために、明日からたばこを吸うのをやめてちょうだい。」\n夫「（ **そんなに** ）厳しいことを言わないでよ。」\n*Tsuma: \"Anata no karada no tame ni, ashita kara tabako o suu no o yamete chōdai.\"\nOtto: \"(**Sonna ni**) kibishii koto o iwanaide yo.\"*\n* **Meaning:**\n*\"Wife: \"For the sake of your health, please quit smoking starting tomorrow.\"\nHusband: \"Don't say something so strict!\"\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Speaker A says X] → Speaker B: そんなに + [Adj] 〜ないで** = Don't be THAT [strict]!\n* 📖 **Explanation:** Just like そこ/それ, **そ-series (そんな・そんなに)** points back to what the *listener* just said ('stop smoking starting tomorrow!').\n* 🇯🇵 **日本語ポイント:** 相手が直前に言った言葉（「明日からたばこをやめて」）の内容や程度を指すときは「そ」系の「そんなに」を使います。\n* 🎯 **Exam Clue:** Dialogue rule: **Listener's words → そんなに** ('don't be *that* strict about what you just said')!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 こんなに:** こ-series refers to the *speaker's own* side/degree, not the wife's demand. / 自分側のことを指します。\n* **3 あんなに:** あ-series refers to a third party or distant shared past, not what the wife just said. / 遠い対象・過去のことを指します。\n* **4 どんなに:** Question/exclamatory adverb ('how very'), doesn't fit reacting to a request with *言わないで*. / 疑問・感嘆の副詞です。\n"
