              "explanation": "The correct answer is **4 気味** (*gimi*).\n💡 **Quick Takeaway**: **N / V-stem + 気味 (ぎみ)** means *'a touch of / slightly coming down with'* (like 風邪気味).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n私は昨日から風邪（ **気味で** / **気味** ）、熱が少しある。\n*Watashi wa kinō kara kaze (**gimi**), netsu ga sukoshi aru.*\n* **Meaning:**\n*\"I have had a touch of a cold since yesterday, and have a slight fever.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[風邪 / 疲れ / 遅れ] + 気味 (ぎみ)** = a slight touch / tendency of ~\n* 📖 **Explanation:** 気味 (*-gimi*) attaches to nouns or verb stems to show a mild negative physical or situational tendency starting to show (風邪気味 = slight cold, 疲れ気味 = slightly tired). Note: **っぽい** does not attach cleanly to 風邪 without sounding 'childish/cold-like', and **げ** takes な-adj feelings (*さびしげ*).\n* 🇯🇵 **日本語ポイント:** 「名詞／動詞ます形語幹＋気味（ぎみ）」は「少し〜の傾向・兆候がある」を表します。「風邪気味」は定番の複合語です。\n* 🎯 **Exam Clue:** Classic N3 compound: **風邪気味 (かぜぎみ, touch of a cold)** + **熱が少しある (slight fever)**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 っぽい:** Means '-ish / tends to act like' (e.g., 子どもっぽい, 怒りっぽい), not used for catching a slight cold (*風邪気味*). / 「子どもっぽい」など性質・外観に使い、「風邪気味」とは言いません。\n* **2 ほど:** Means 'to the extent of', doesn't form 'slight touch of a cold'. / 「風邪ほど」は意味が合いません。\n* **3 げ:** Attaches to adjectives/emotion verbs (*悲しげ* = looking sad), never *風邪*. / 形容詞語幹などにつき「〜そうな様子」を表します。\n"
