              "instruction": "問題1 次の文の（　　）に入れるのに最もよいものを、一つえらびなさい。",
              "explanation": "The correct answer is **2 ついでに** (*tsuide ni*).\n💡 **Quick Takeaway**: **V た-form + ついでに** means *'while I was out doing X, I also took the chance to do Y'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n近所へ散歩に行った（ **ついでに** ）、スーパーで牛乳を買ってきました。\n*Kinjo e sanpo ni itta (**tsuide ni**), sūpā de gyūnyū o katte kimashita.*\n* **Meaning:**\n*\"While I was out taking a walk in the neighborhood, I also stopped by the supermarket and bought milk.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Main Action た-form/Dict/Noun の] + ついでに、[Bonus Action]** = while at it / on the way\n* 📖 **Explanation:** ついでに describes taking advantage of one main outing (a neighborhood walk) to conveniently get a secondary errand done (buying milk).\n* 🇯🇵 **日本語ポイント:** 「〜ついでに」は主目的の行動（「散歩に行く」）の機会を利用して、ついでに別の用事（「牛乳を買う」）も済ませる表現です。\n* 🎯 **Exam Clue:** Spot **散歩 (main outing) ＋ スーパーで牛乳を買う (convenient side errand)** → **ついでに**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 かたがた:** *かたがた* ('for the dual purpose of', N1/N2 formal) attaches directly to nouns (*お礼かたがた*), NOT verb た-form *行った*. / 名詞に接続する硬い表現で「行った」にはつきません。\n* **3 かわりに:** Means 'instead of going for a walk' (substitution), whereas both walk and shopping happened! / 「散歩せずに代わりに」となり意味が異なります。\n* **4 ままに:** Means 'leaving things as they are / following impulses', doesn't fit errands. / 状態維持や思いのままを表します。\n"
