              "correctIndex": 2,
              "sectionType": "grammar-reading",
              "explanation": "The correct answer is **3 ということにはならない** (*to iu koto ni wa naranai*).\n💡 **Quick Takeaway**: **〜ということにはならない** rejects flawed logic (*'just because X doesn't mean it's okay to do Y'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n自分がいじめられたから、友だちをいじめていい（ **ということにはならない** ）。\n*Jibun ga ijimerareta kara, tomodachi o ijimete ii (**to iu koto ni wa naranai**).*\n* **Meaning:**\n*\"Just because you were bullied yourself does not mean it's okay to bully your friends.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Bad premise] から、[Wrong conclusion] ということにはならない** = does not follow / justify...\n* 📖 **Explanation:** 〜ということにはならない logically rejects drawing an invalid conclusion ('A doesn't justify B'). Fits ethics/reasoning statements cleanly.\n* 🇯🇵 **日本語ポイント:** 「〜だからといって、〜ということにはならない」は「そのような結論・理屈にはならない」と論理を否定する表現です。\n* 🎯 **Exam Clue:** Reason-to-conclusion denial (**いじめられたから、いじめていい〜**) → **ということにはならない**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 というはずではない:** Ungrammatical blend; expected impossibility uses *はずがない*, not *というはずではない*. / 不自然な表現です。\n* **2 といったものだ:** Means 'is something like ~', affirmative and wrong meaning. / 例示・本質を表し意味が合いません。\n* **4 というわけだ:** Affirmative ('so that means it's okay to bully'), completely opposite ethics! / 肯定の結論になり正反対です。\n"
