              "correctIndex": 3,
              "sectionType": "grammar-reading",
              "explanation": "The correct answer is **4 見かけないことはない** (*mikakenai koto wa nai*).\n💡 **Quick Takeaway**: **〜ないことはない** + present-tense *行くと* = *'whenever you go to a bookstore, you are bound to see them'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n書店に行くと、このようなタイトルの本を［ 20 **見かけないことはない** ］。\n*Shoten ni iku to, kono yō na taitoru no hon o [**mikakenai koto wa nai**].*\n* **Meaning:**\n*\"Whenever you go to a bookstore, there is never a time you don't spot books with titles like these.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Present Habit: 〜と] + 〜ないことはない** = double negative = always / invariably see\n* 📖 **Explanation:** Because the first paragraph is talking about *current* bookstores (出版されている, 行くと, present tense), **見かけないことはない** ('you're guaranteed to run across them') matches both the tense and meaning (unlike past-tense *見かけたものだ*).\n* 🇯🇵 **日本語ポイント:** 現在もたくさん出版されていて「書店に行くと（現在形）必ず見かける」という意味になる二重否定「見かけないことはない」が正解です。\n* 🎯 **Exam Clue:** Check tense! **書店に行くと** (present general truth) → must be present **見かけないことはない** (NOT past nostalgic *見かけたものだ*)!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 見かけたものだ:** Past-tense nostalgia ('I used to see them back in the day'), clashing with present *出版されている* and *行くと*. / 過去の回想になり現在形と合いません。\n* **2 見かけることなどない:** Means 'you never see them at all'—exact opposite! / 「全く見かけない」となり矛盾します。\n* **3 見かけないといってよい:** Means 'one might say you don't see them'—opposite meaning! / 「見かけない」の否定になり矛盾します。\n"
