              "explanation": "The correct answer is **4 ことだから** (*koto da kara*).\n💡 **Quick Takeaway**: **[Person] のことだから** means *'knowing how capable that person is, I'm sure they'll...'*.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nなんでもできるあの人の（ **ことだから** ）、この仕事もちゃんとやってくれると思います。\n*Nandemo dekiru ano hito no (**koto da kara**), kono shigoto mo chanto yatte kureru to omoimasu.*\n* **Meaning:**\n*\"Knowing how capable that person is—being able to do anything—I think they will do this job properly too.\"*\n\n---\n\n### Context & Passage Clue\n\n* 📌 **Pattern:** **[Person] の ことだから、[Expected Result]** = Knowing [Person]'s character, surely...\n* 📖 **Explanation:** 〜のことだから predicts what someone will naturally do based on their well-known personality or track record (here: someone who can do anything).\n* 🇯🇵 **日本語ポイント:** 「（人）のことだから」は、その人の性格や普段の様子から「あの人ならきっと〜するはずだ」と予想する文型です。\n* 🎯 **Exam Clue:** Spot **なんでもできるあの人の ( )、〜と思います** (character-based prediction) → **ことだから**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 ことに:** Used after emotion adjectives (*うれしいことに*), not people's names/pronouns. / 人の性格からの予想には使いません。\n* **2 ことには:** Means 'the thing is...' (*困ったことには*), doesn't predict behavior from personality. / 前置き表現で合いません。\n* **3 ことから:** Means 'from the fact that' (for objective events/clues, not *あの人のことから*). / 根拠の事柄に使い、「人の性格」には「ことだから」を使います。\n"
