              "explanation": "The correct answer is **1 出られそうにないので** (*deraresō ni nai node*).\n💡 **Quick Takeaway**: **V-stem + そうにない** expresses strong likelihood of inability (*'unlikely to be able to answer the phone'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n会議が始まると電話に（ **出られそうにないので** ）、メールを送って下さい。\n*Kaigi ga hajimaru to denwa ni (**deraresō ni nai node**), mēru o okutte kudasai.*\n* **Meaning:**\n*\"Since it looks unlikely I'll be able to answer the phone once the meeting starts, please send an email.\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Potential ます-stem: 出られ] + そうにない** = doesn't look like I'll be able to ~\n* 📖 **Explanation:** Potential verb 出られる (*can answer*) → stem **出られ** + **そうにない** = 'doesn't look like I'll be able to answer', giving a natural reason to email instead.\n* 🇯🇵 **日本語ポイント:** 可能形「出られる」の語幹に「そうにない（〜できそうもない）」をつけて「電話に出られない見込みだ」と伝えています。\n* 🎯 **Exam Clue:** Reason for emailing instead of calling (**会議が始まると〜、メールを送って**) → **出られそうにないので**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **2 出ようとしないので:** Means 'refuses to try answering', implying stubbornness rather than being busy in a meeting! / 「出ようとする意志がない」となり不自然です。\n* **3 出るようなので:** Means 'since it looks like I will answer', contradicting 'please send an email instead'! / 「出る」ならメールは不要で矛盾します。\n* **4 出るそうなので:** Means 'I heard I will answer', nonsensical for one's own schedule! / 自分の行動に伝聞の「そうだ」は使いません。\n"
