              "explanation": "The correct answer is **4 結婚しているんだって** (*kekkon shite iru n da tte*).\n💡 **Quick Takeaway**: **確か〜んだって** reports casual hearsay you recall hearing (*'If I remember right, I heard he's married!'*).\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\nパク「キムさんって、とてもすてきな人だね。」\n木村「でも、キムさんは確か（ **結婚しているんだって** ）。」\n*Paku: \"Kimu-san tte, totemo suteki na hito da ne.\"\nKimura: \"Demo, Kimu-san wa tashika (**kekkon shite iru n da tte**).\"*\n* **Meaning:**\n*\"Park: \"Kim-san is a really wonderful person, isn't he?\"\nKimura: \"Yeah, though if I remember right, I heard Kim-san is married.\"\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **確か + [Plain Clause] + んだって** = If I recall correctly, I heard that... (casual hearsay)\n* 📖 **Explanation:** 〜だって / 〜んだって is casual spoken hearsay ('I heard that...'). Paired with **確か** ('if I recall correctly') and **でも** ('but...'), it breaks the news gently!\n* 🇯🇵 **日本語ポイント:** 「確か〜んだって」は記憶をたどりながら「〜と聞いているよ」と伝える話し言葉の伝聞表現です。\n* 🎯 **Exam Clue:** Signal word **確か (if I recall)** + casual dialogue (**でも〜**) → hearsay **〜んだって**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **1 結婚していそうだよ:** Means 'looks married' (visual guess), clashing with recalling a fact *確か*. / 見た目の推量になり「確か」と合いません。\n* **2 結婚していっこないって:** Means 'no way he's married', contradicting the warning *でも* ('Wait, but...'). / 「でも（しかし）」の逆接に合いません。\n* **3 結婚しているわけだよ:** Means 'so that explains why he's married', illogical after 'he's a wonderful person'. / 理由づけの「わけだ」は不自然です。\n"
