              "explanation": "The correct answer is **1 そんなときは** (*sonna toki wa*).\n💡 **Quick Takeaway**: **そんなときは** (*in such cases / when that's the situation*) refers directly to the reader's time/distance obstacle just mentioned.\n\n---\n\n### Sentence Breakdown\n\n* **Japanese:**\n山まで遠いし、行く時間もない、という人も多いだろう。［ 21 **そんなときは** ］、都会の中の森に出かけてみてはいかがだろうか。\n*Yama made tōi shi, iku jikan mo nai, to iu hito mo ōi darō. [**Sonna toki wa**], tokai no naka no mori ni dekakete mite wa ikaga darō ka.*\n* **Meaning:**\n*\"Many people probably feel the mountains are far and they have no time to go. In such cases, why not try heading out to a forest right inside the city?\"*\n\n---\n\n### Pattern to Memorize\n\n* 📌 **Pattern:** **[Reader's Problem] 。そんなときは、[Solution Proposal 〜てみてはいかが]** = In such a case, why not...?\n* 📖 **Explanation:** そ-series (**そんなときは**) refers back to the hypothetical problem just mentioned ('too far and no time to go to the mountains') before offering a practical alternative.\n* 🇯🇵 **日本語ポイント:** 直前の「山は遠くて行く時間もない」という読者の状況を受けて「そんなときは〜してはいかがですか」と提案しています。\n* 🎯 **Exam Clue:** Spot **Problem → ( )、〜てみてはいかがだろうか (Suggestion)** → **そんなときは**!\n\n---\n\n### Why Other Options Don't Fit\n\n* **2 あんなときは:** あ-series points to distant past events, not the condition just described in text. / 過去の遠い出来事を指します。\n* **3 そちらのときは:** *そちら* refers to a place/person/direction, not a situation/time. / 場所や相手側を指す語です。\n* **4 あちらのときは:** *あちら* refers to a distant place/person, not a situation. / 遠い場所や人を指す語です。\n"
